export function sortMessages(messages: ChatMessage[]): ChatMessage[] {
  return messages
    .map((message, index) => ({ message, index }))
    .sort(
      (left, right) =>
        left.message.timestamp - right.message.timestamp ||
        left.index - right.index,
    )
