pub struct Task {
    pub name: &'static str,
    pub priority: i32,
}

pub fn order_by_priority(tasks: &mut [Task]) {
    tasks.sort_by(|a, b| b.priority.cmp(&a.priority));
}

fn main() {
    let mut tasks = vec![
        Task { name: "quartz", priority: 9 },
        Task { name: "reed", priority: 2 },
        Task { name: "birch", priority: 6 },
    ];
    order_by_priority(&mut tasks);
    for task in tasks {
        println!("{}: {}", task.name, task.priority);
    }
}

