def monthly_usage(records):
    totals = {}
    for record in records:
        month = record["date"][:7]
        bucket = totals.setdefault(
            month, {"month": month, "requests": 0, "bytes": 0}
        )
        bucket["requests"] += record["requests"]
        bucket["bytes"] += record["bytes"]
    return [totals[month] for month in sorted(totals)]

