export interface ReferenceRange {
  lower: number;
  upper: number;
}

export function markStrepOutOfRange(
  records: readonly StrepRecord[],
  range: ReferenceRange,
): Array<StrepRecord & { strepOutOfRange: boolean }> {
  return records.map((record) => ({
    ...record,
    strepOutOfRange:
      record.strepResult < range.lower || record.strepResult > range.upper,
  }));
}

