const button = document.querySelector('#account-menu-button');
const menu = document.querySelector('#account-menu');

button.addEventListener('click', () => {
  const open = menu.style.display === 'none';
  menu.style.display = open ? 'block' : 'none';
  button.setAttribute('aria-expanded', String(open));
});

function nextIndex(index, step, length) {
  if (length === 0) return -1;
  return (index + step + length) % length;
}

function initMenu(button, menu) {
  const items = Array.from(menu.querySelectorAll('[role="menuitem"]'));
  menu.style.display = 'none';

  button.addEventListener('click', () => {
    const open = menu.style.display === 'none';
    menu.style.display = open ? 'block' : 'none';
    button.setAttribute('aria-expanded', String(open));
  });

  button.addEventListener('keydown', event => {
    if (event.key !== 'ArrowDown' && event.key !== 'Enter') return;
    event.preventDefault();
    menu.style.display = 'block';
    button.setAttribute('aria-expanded', 'true');
    if (items[0]) items[0].focus();
  });

  menu.addEventListener('keydown', event => {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      let index = items.indexOf(document.activeElement);
      const step = event.key === 'ArrowDown' ? 1 : -1;
      if (index < 0) index = step > 0 ? -1 : 0;
      const target = items[nextIndex(index, step, items.length)];
      if (target) target.focus();
      return;
    }

    if (event.key === 'Enter') {
      const item = items.find(candidate => candidate === document.activeElement);
      if (!item) return;
      event.preventDefault();
      item.click();
      menu.style.display = 'none';
      button.setAttribute('aria-expanded', 'false');
      button.focus();
    }
  });
}

if (typeof document !== 'undefined') {
  const button = document.querySelector('#account-menu-button');
  const menu = document.querySelector('#account-menu');
  if (button && menu) initMenu(button, menu);
}

if (typeof module !== 'undefined') module.exports = { initMenu, nextIndex };

