#include "ringbuf.h"

void rb_init(RingBuf *rb) {
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
}

bool rb_write(RingBuf *rb, uint8_t value) {
    if (rb == NULL) {
        return false;
    }
    rb->data[rb->head] = value;
    rb->head = (rb->head + 1) % RB_CAPACITY;
    if (rb->count < RB_CAPACITY) {
        rb->count++;
    } else {
        rb->tail = (rb->tail + 1) % RB_CAPACITY;
    }
    return true;
}

bool rb_read(RingBuf *rb, uint8_t *value) {
    if (rb == NULL || value == NULL || rb->count == 0) {
        return false;
    }
    *value = rb->data[rb->tail];
    rb->tail = (rb->tail + 1) % RB_CAPACITY;
    rb->count--;
    return true;
}

