import struct
from pathlib import Path


def read_header(path):
    with Path(path).open("rb") as stream:
        raw = stream.read(12)
    if len(raw) != 12:
        raise ValueError("header must contain 12 bytes")
    magic, version, record_count = struct.unpack("<4sII", raw)
    return {"magic": magic, "version": version, "record_count": record_count}

