import csv
from pathlib import Path
from typing import TextIO


def load_cells(source: str | Path | TextIO) -> list[dict[str, str | float]]:
    """Load cell identifiers and capacities from a partner CSV."""
    if hasattr(source, "read"):
        stream = source
        should_close = False
    else:
        stream = open(source, newline="", encoding="utf-8")
        should_close = True

    try:
        reader = csv.DictReader(stream)
        required = {"cell_id", "capacity_mAh"}
        if reader.fieldnames is None or not required.issubset(reader.fieldnames):
            raise ValueError("CSV requires cell_id and capacity_mAh columns")

        cells: list[dict[str, str | float]] = []
        for row_number, row in enumerate(reader, start=2):
            cell_id = (row.get("cell_id") or "").strip()
            capacity_text = (row.get("capacity_mAh") or "").strip()
            if not cell_id:
                raise ValueError(f"row {row_number}: missing cell_id")
            try:
                capacity = float(capacity_text)
            except ValueError as exc:
                raise ValueError(
                    f"row {row_number}: invalid capacity_mAh {capacity_text!r}"
                ) from exc
            cells.append({"cell_id": cell_id, "capacity_mAh": capacity})
        return cells
    finally:
        if should_close:
            stream.close()

