def normalize_sql(source: str) -> str:
    """Remove surrounding blank lines from a SQL snippet."""
    lines = source.splitlines()
    while lines and not lines[0].strip():
        lines.pop(0)
    while lines and not lines[-1].strip():
        lines.pop()
    return "\n".join(lines)

