from collections import defaultdict

def parse_formula(formula):
    counts = defaultdict(int)
    index = 0
    while index < len(formula):
        if not formula[index].isupper():
            raise ValueError(f"invalid symbol at position {index}")
        end = index + 1
        while end < len(formula) and formula[end].islower():
            end += 1
        symbol = formula[index:end]
        digit_end = end
        while digit_end < len(formula) and formula[digit_end].isdigit():
            digit_end += 1
        count = int(formula[end:digit_end] or "1")
        counts[symbol] += count
        index = digit_end
    return dict(counts)

