import csv
from pathlib import Path


def load_two_hour_glucose(path: str | Path) -> list[tuple[str, float]]:
    required = ("patient_id", "two_hour_glucose_mg_dl")
    readings = []
    with Path(path).open(newline="", encoding="utf-8") as stream:
        reader = csv.DictReader(stream)
        if reader.fieldnames is None or any(name not in reader.fieldnames for name in required):
            raise ValueError("CSV requires patient_id and two_hour_glucose_mg_dl columns")
        for row_number, row in enumerate(reader, start=2):
            patient_id = (row.get("patient_id") or "").strip()
            raw_value = (row.get("two_hour_glucose_mg_dl") or "").strip()
            if not patient_id:
                raise ValueError(f"Missing patient_id on row {row_number}")
            try:
                value = float(raw_value)
            except ValueError as exc:
                raise ValueError(f"Invalid glucose value on row {row_number}") from exc
            readings.append((patient_id, value))
    return readings

