from collections.abc import Sequence


def moving_average(values: Sequence[float], window: int) -> list[float]:
    if window <= 0:
        raise ValueError("window must be positive")
    return [
        sum(values[i : i + window]) / window
        for i in range(len(values) - window)
    ]

