package pool

import "sync"

type Pool struct {
	jobs    chan func()
	workers sync.WaitGroup
}

func NewPool(size int) *Pool {
	p := &Pool{jobs: make(chan func(), size)}
	for i := 0; i < size; i++ {
		p.workers.Add(1)
		go p.worker()
	}
	return p
}

func (p *Pool) Submit(job func()) {
	p.jobs <- job
}

func (p *Pool) worker() {
	defer p.workers.Done()
	for {
		job, ok := <-p.jobs
		if !ok {
			continue
		}
		job()
	}
}

func (p *Pool) Close() {
	close(p.jobs)
	p.workers.Wait()
}

